insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Local Solutions', 'Communities often face problems that national policies cannot solve quickly. Local initiatives, such as shared transportation, neighborhood tutoring, or volunteer repair groups, can respond to specific needs. Their strength lies in familiarity with local conditions. However, local projects also need organization and resources; good intentions alone rarely sustain them. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 70, 7, 'local initiatives', 'approved');
