insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Museums in the Digital Age', 'Digital exhibitions allow museums to reach visitors who cannot travel, but they do not fully replace the experience of seeing objects in person. Online access can provide context, images, and expert explanations. Physical visits, however, offer scale, atmosphere, and a sense of presence. The strongest museums use digital tools as an extension of the visit, not as a substitute for it. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 82, 7, 'museums', 'approved');
